#include "scenario/scenario.hpp"
#include <iostream>
#include <string>
#include <vector>
#include <cmath>
#include <iomanip>
int main(int argc,char**argv){if(argc<2||std::string(argv[1])=="--help"||std::string(argv[1])=="-h"){std::cout<<"scenario-calculator <run|compare|diff|cohort|seek|breakeven|sensitivity|check> <scenario.ini> [--format text|csv|markdown|json]\nAll results are HYPOTHETICAL / NOT A FORECAST.\n";return argc<2?1:0;}std::string cmd=argv[1],format="text";if(cmd!="run"&&cmd!="compare"&&cmd!="diff"&&cmd!="cohort"&&cmd!="seek"&&cmd!="breakeven"&&cmd!="sensitivity"&&cmd!="check"){std::cerr<<"Unknown command: "<<cmd<<"\n";return 2;}if(argc<3){std::cerr<<"A scenario file is required\n";return 2;}std::vector<std::string> files;for(int i=2;i<argc;++i){std::string a=argv[i];if(a=="--format"&&i+1<argc)format=argv[++i];else if(a.rfind("--",0)==0){std::cerr<<"Unknown flag: "<<a<<"\n";return 2;}else files.push_back(a);}try{if(cmd=="compare"||cmd=="diff"){if(files.size()!=2){std::cerr<<cmd<<" requires exactly two scenario files\n";return 2;}auto a=scenario::load(files[0]),b=scenario::load(files[1]);auto check=[](const scenario::Model&m){auto e=scenario::validate(m);if(!e.empty())throw std::runtime_error("invalid scenario: "+e.front());};check(a);check(b);if(cmd=="compare"){std::cout<<"HYPOTHETICAL / NOT A FORECAST — scenario comparison\n";for(const auto&m:{a,b}){double normalized=m.price*(m.period=="weekly"?52.0/12:m.period=="quarterly"?1.0/3:m.period=="annual"?1.0/12:1);std::cout<<std::left<<std::setw(30)<<m.name<<" currency="<<m.currency<<" monthly_price="<<(m.has_price?m.currency+" "+std::to_string(normalized):"unavailable")<<" target_payers="<<(m.has_price?std::to_string(static_cast<long long>(std::ceil(m.target/normalized))):"unavailable")<<" replacements="<<(m.has_price&&m.has_loss?std::to_string(static_cast<long long>(std::ceil(m.target/normalized*m.loss))):"unavailable")<<"\n";}}else{std::cout<<"HYPOTHETICAL / NOT A FORECAST — scenario differences\n";auto d=[&](const std::string&k,const std::string&x,const std::string&y){if(x!=y)std::cout<<k<<": "<<a.name<<"="<<x<<"; "<<b.name<<"="<<y<<"\n";};d("currency",a.currency,b.currency);d("target_mrr",std::to_string(a.target),std::to_string(b.target));d("price",a.has_price?std::to_string(a.price):"unavailable",b.has_price?std::to_string(b.price):"unavailable");d("period",a.period,b.period);d("expiry_loss",a.has_loss?std::to_string(a.loss):"unavailable",b.has_loss?std::to_string(b.loss):"unavailable");d("first_open_to_activation",a.has_activation?std::to_string(a.open_activation):"unavailable",b.has_activation?std::to_string(b.open_activation):"unavailable");d("activation_to_paid",a.has_activation?std::to_string(a.activation_paid):"unavailable",b.has_activation?std::to_string(b.activation_paid):"unavailable");auto outputs=[](const scenario::Model&m){double rate=m.price*(m.period=="weekly"?52.0/12:m.period=="quarterly"?1.0/3:m.period=="annual"?1.0/12:1);long long n=m.has_price?static_cast<long long>(std::ceil(m.target/rate)):0;return std::pair<std::string,std::string>{m.has_price?std::to_string(n):"unavailable",m.has_price&&m.has_loss?std::to_string(static_cast<long long>(std::ceil(n*m.loss))):"unavailable"};};auto x=outputs(a),y=outputs(b);d("output.active_payers",x.first,y.first);d("output.monthly_replacements",x.second,y.second);}return 0;}if(files.size()!=1){std::cerr<<cmd<<" requires exactly one scenario file\n";return 2;}auto m=scenario::load(files.front());std::cout<<scenario::execute(m,cmd,format);}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}return 0;}
